-- SC-2A migration 0003: clinic-scoped patient records (Arch 11.12, FR-PAT-001/002/006).
-- Part 1 is generated by Prisma (phone_last4 changed to a GENERATED column); part 2 is hand-written (ADR-019).

-- CreateEnum
CREATE TYPE "patient_source" AS ENUM ('QR_BOOKING', 'QR_WALK_IN', 'STAFF');

-- CreateTable
CREATE TABLE "patient" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "clinic_id" UUID NOT NULL,
    "full_name" VARCHAR(100) NOT NULL,
    "name_normalized" VARCHAR(100) NOT NULL,
    "phone_e164" VARCHAR(16),
    "no_phone_reason" VARCHAR(200),
    "phone_last4" CHAR(4) GENERATED ALWAYS AS (right(phone_e164, 4)) STORED,
    "source" "patient_source" NOT NULL,
    "anonymized_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "patient_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "patient_clinic_id_phone_e164_idx" ON "patient"("clinic_id", "phone_e164");

-- CreateIndex
CREATE UNIQUE INDEX "patient_clinic_id_id_key" ON "patient"("clinic_id", "id");

-- AddForeignKey
ALTER TABLE "patient" ADD CONSTRAINT "patient_clinic_id_fkey" FOREIGN KEY ("clinic_id") REFERENCES "clinic"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ===================================================================================================
-- Part 2 — hand-written objects (ADR-019)
-- ===================================================================================================

-- A patient always has a phone, unless anonymised or registered through the staff no-phone exception (BR-037).
ALTER TABLE "patient" ADD CONSTRAINT "patient_phone_presence_check" CHECK (anonymized_at IS NOT NULL OR phone_e164 IS NOT NULL OR no_phone_reason IS NOT NULL);
ALTER TABLE "patient" ADD CONSTRAINT "patient_phone_format_check" CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{6,14}$');
ALTER TABLE "patient" ADD CONSTRAINT "patient_name_check" CHECK (length(full_name) BETWEEN 2 AND 100 AND length(name_normalized) >= 1);

-- FR-PAT-002 matching key within one clinic; also serialises concurrent find-or-create.
CREATE UNIQUE INDEX "patient_match_key" ON "patient" ("clinic_id", "phone_e164", "name_normalized")
  WHERE anonymized_at IS NULL AND phone_e164 IS NOT NULL;
-- FR-PAT-003 staff search by last 4 digits and partial name.
CREATE INDEX "patient_clinic_last4_idx" ON "patient" ("clinic_id", "phone_last4");
CREATE INDEX "patient_name_trgm_idx" ON "patient" USING gin ("name_normalized" gin_trgm_ops);

GRANT SELECT, INSERT, UPDATE, DELETE ON "patient" TO sc_app;
GRANT ALL ON "patient" TO sc_owner;
